async handle(req: Request): Promise<Response> {
  const route = this.routes.get(`${req.method} ${req.path}`);
  if (!route) return { status: 404 };
  const chain = this.middleware.reduceRight<Handler>((next, mw) => (r) => mw(r, next), route);
  return chain(req);
}

export const requireAuth: Middleware = async (req, next) => {
  const header = req.headers["authorization"];
  if (!header?.startsWith("Bearer ")) return { status: 401 };
  const user = await verifyToken(header.slice(7));
  if (!user) return { status: 401 };
  req.user = user;
  return next(req);
};

export function rateLimit(limiter: RateLimiter): Middleware {
  return async (req, next) => {
    const user = req.user;
    if (!user) return next(req);
    const decision = limiter.check(user.id, user.plan);
    if (!decision.allowed) {
      return { status: 429, headers: { "retry-after": String(decision.retryAfter) } };
    }
    return next(req);
  };
}

