private bucketFor(clientId: string, plan: Plan, now: number): TokenBucket {
  let bucket = this.buckets.get(clientId);
  if (!bucket) {
    const { burst, perSecond } = LIMITS[plan];
    bucket = new TokenBucket(burst, perSecond, now);
    this.buckets.set(clientId, bucket);
  }
  return bucket;
}

refill(now: number): void {
  const elapsed = (now - this.updatedAt) / 1000;
  this.tokens = Math.min(this.capacity, this.tokens + elapsed * this.refillPerSecond);
  this.updatedAt = now;
}

tryTake(): boolean {
  if (this.tokens < 1) return false;
  this.tokens -= 1;
  return true;
}

secondsUntilNext(): number {
  return this.tokens >= 1 ? 0 : (1 - this.tokens) / this.refillPerSecond;
}

export const LIMITS: Record<Plan, { burst: number; perSecond: number }> = {
  free: { burst: 20, perSecond: 1 },
  pro: { burst: 100, perSecond: 10 },
};

